package org.lira.receiver;
import java.nio.file.*;import java.io.*;import java.security.*;import org.json.*;
public final class DictationEngineTest {
 static class Time implements DictationEngine.Clock {long t;public long now(){return t;}}
 static class Sound implements DictationEngine.Audio {DictationEngine.Completion done;int repeats;int plays;public void play(String t,String h,String a,int r,DictationEngine.Completion c){done=c;repeats=r;plays++;}public void stop(){}void drain(){DictationEngine.Completion d=done;done=null;d.done(true);}}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static JSONObject command(DictationEngine e,String command)throws Exception {JSONObject s=e.status();return new JSONObject().put("task_id",s.getJSONObject("task").getString("task_id")).put("command_id",java.util.UUID.randomUUID().toString()).put("expected_state_revision",s.getLong("state_revision")).put("command",command);}
 public static void main(String[] args)throws Exception {
 JSONObject task=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));task.getJSONObject("parameters").put("expanded_word_seconds",2).put("expanded_timer_anchor","after_playback");task.put("content_hash",DictationSpec.contentHash(task));
 File dir=Files.createTempDirectory("engine-test").toFile();TaskAssetStore assets=new TaskAssetStore(new File(dir,"assets"));java.util.Set<String> names=new java.util.HashSet<>();names.add("prompt.prepare");names.add("prompt.finish");names.add("prompt.pinyin");JSONArray ls=task.getJSONArray("lessons");for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i);JSONArray w=l.getJSONArray("expanded_words");for(int j=0;j<w.length();j++)names.add(w.getJSONObject(j).getString("audio_asset_id"));if(!l.isNull("recitation"))names.add(l.getJSONObject("recitation").getString("prompt_audio_asset_id"));}
 JSONArray manifest=new JSONArray();byte[] pcm={0,0};StringBuilder sha=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(pcm))sha.append(String.format("%02x",b&255));for(String id:names){assets.begin(task.getString("task_id"),task.getString("content_hash"),id,2,sha.toString());assets.append(task.getString("task_id"),task.getString("content_hash"),id,0,pcm);assets.commit(task.getString("task_id"),task.getString("content_hash"),id);manifest.put(new JSONObject().put("asset_id",id).put("sha256",sha.toString()).put("pcm_bytes",2).put("frames",1).put("sample_rate",24000).put("channels",1));}
 JSONObject wrapper=new JSONObject().put("task",task).put("manifest",new JSONObject().put("task_id",task.getString("task_id")).put("content_hash",task.getString("content_hash")).put("assets",manifest));Time clock=new Time();Sound sound=new Sound();DictationStateStore store=new DictationStateStore(new File(dir,"state"));DictationEngine.Display display=new DictationEngine.Display(){public void show(String k,JSONArray w,String t){}};DictationEngine e=new DictationEngine(clock,sound,display,store,assets);e.start(wrapper);check(sound.plays==1,"prepare audio");clock.t=90000;e.tick();check(e.status().getInt("index")==0,"no timer before drain");sound.drain();check(e.status().getInt("index")==1,"prepare drained");DictationEngine.Completion old=sound.done;e.control(command(e,"pause"));old.done(true);clock.t+=100000;e.tick();check(e.status().getInt("index")==1,"late callback fenced");e.control(command(e,"continue"));sound.drain();long index=e.status().getInt("index");clock.t+=1999;e.tick();check(e.status().getInt("index")==index,"duration after audio");clock.t++;e.tick();check(e.status().getInt("index")>index,"deadline advances");JSONObject previous=command(e,"previous");e.control(previous);int back=e.status().getInt("index");clock.t+=100000;e.tick();check(e.status().getInt("index")==back&&e.status().getString("state").equals("paused"),"back pauses");e.control(previous);check(e.status().getInt("index")==back,"duplicate command no second back");DictationEngine recovered=new DictationEngine(clock,new Sound(),display,store,assets);check(recovered.status().getString("state").equals("paused_recovery"),"restart stays paused");check(recovered.status().getInt("run_epoch")==1,"task-bound callback epoch survives restart");JSONArray events=recovered.pendingEvents();for(int i=0;i<events.length();i++){check(events.getJSONObject(i).getInt("sequence")==i+1,"contiguous sequence");check(events.getJSONObject(i).getInt("run_epoch")==1,"every restart event retains repository-bound epoch");}String event=events.getJSONObject(0).getString("event_id");recovered.ack(event);check(recovered.pendingEvents().length()==events.length()-1,"durable ack");recovered.control(command(recovered,"cancel"));JSONArray pending=recovered.pendingEvents();JSONObject nextTask=new JSONObject(task.toString()).put("task_id","another-task");nextTask.put("content_hash",DictationSpec.contentHash(nextTask));JSONObject other=new JSONObject().put("task",nextTask).put("manifest",new JSONObject());try{recovered.start(other);throw new AssertionError("terminal pending outbox discarded");}catch(IllegalStateException expected){}check(recovered.pendingEvents().toString().equals(pending.toString()),"rejected new task preserves old events exactly");DictationEngine again=new DictationEngine(clock,new Sound(),display,store,assets);check(again.pendingEvents().toString().equals(pending.toString()),"terminal pending events survive process restart");System.out.println("DictationEngine timing, drain, history, retry, restart stable epoch, terminal outbox passed");
 }
}
